// @vitest-environment jsdom
import { describe, expect, it } from 'vitest';
import { AppUI } from './index';

const openBoard = (playerRating?: number): HTMLElement => {
  const root = document.createElement('div');
  new AppUI(root, {}, playerRating === undefined ? {} : { playerRating });
  root.querySelector<HTMLElement>('[data-nav="leaderboard"]')!.click();
  return root;
};

const rowsOf = (root: HTMLElement): HTMLElement[] =>
  [...root.querySelectorAll<HTMLElement>('.leaderboard__table tbody tr')];

const ratingOf = (row: HTMLElement): number =>
  Number(row.querySelector('.leaderboard__rating')!.textContent!.replace(/\D/g, ''));

describe('leaderboard screen', () => {
  it('is reachable from the main menu and lists 50+ ranked players', () => {
    const root = openBoard(1500);
    expect(root.querySelector('.leaderboard')).not.toBeNull();
    const rows = rowsOf(root);
    expect(rows.length).toBeGreaterThanOrEqual(50);
    expect(rows.map((row) => row.querySelector('.leaderboard__rank')!.textContent)).toEqual(
      rows.map((_, index) => `#${index + 1}`),
    );
    for (let index = 1; index < rows.length; index += 1) {
      expect(ratingOf(rows[index - 1]!)).toBeGreaterThanOrEqual(ratingOf(rows[index]!));
    }
  });

  it('highlights the local player at the position of the saved rating', () => {
    const root = openBoard(1500);
    const highlighted = rowsOf(root).filter((row) => row.classList.contains('leaderboard__row--highlight'));
    expect(highlighted).toHaveLength(1);
    const you = highlighted[0]!;
    expect(you.dataset.playerId).toBe('local-player');
    expect(ratingOf(you)).toBe(1500);
    const ahead = rowsOf(root).filter((row) => ratingOf(row) > 1500).length;
    expect(you.querySelector('.leaderboard__rank')?.textContent).toBe(`#${ahead + 1}`);
    expect(root.querySelector('[data-leaderboard-summary]')?.textContent).toContain(`#${ahead + 1}`);
  });

  it('moves the player to the top or the bottom with extreme ratings', () => {
    expect(rowsOf(openBoard(3200))[0]?.dataset.playerId).toBe('local-player');
    expect(rowsOf(openBoard(200)).at(-1)?.dataset.playerId).toBe('local-player');
  });

  it('returns to the main menu', () => {
    const root = openBoard();
    root.querySelector<HTMLElement>('[data-nav="main"]')!.click();
    expect(root.querySelector('.leaderboard')).toBeNull();
    expect(root.querySelector('[data-nav="leaderboard"]')).not.toBeNull();
  });
});
