import { describe, expect, it } from 'vitest';
import {
  DEFAULT_PLAYER_RATING,
  PLAYER_RATING_STORAGE_KEY,
  buildLeaderboardStandings,
  loadPlayerRating,
  savePlayerRating,
} from '../src/leaderboard/standings';

const memoryStorage = () => {
  const values = new Map<string, string>();
  return {
    getItem: (key: string) => values.get(key) ?? null,
    setItem: (key: string, value: string) => void values.set(key, value),
  };
};

describe('leaderboard standings', () => {
  it('merges the local player into the AI field and re-ranks every row', () => {
    const entries = buildLeaderboardStandings({
      seed: 'standings-test',
      count: 64,
      player: { id: 'local-player', displayName: 'You', rating: 1500 },
    });
    expect(entries).toHaveLength(65);
    expect(entries.map((entry) => entry.rank)).toEqual(entries.map((_, index) => index + 1));
    for (let index = 1; index < entries.length; index += 1) {
      expect(entries[index - 1]!.rating).toBeGreaterThanOrEqual(entries[index]!.rating);
    }
    const you = entries.find((entry) => entry.id === 'local-player')!;
    expect(you.kind).toBe('human');
    expect(entries.filter((entry) => entry.rating > 1500)).toHaveLength(you.rank - 1);
  });

  it('keeps the generated field untouched when no player is supplied', () => {
    const entries = buildLeaderboardStandings({ seed: 'standings-test', count: 12 });
    expect(entries).toHaveLength(12);
    expect(entries.every((entry) => entry.kind === 'bot')).toBe(true);
  });

  it('derives the win rate and clamps an out-of-range rating', () => {
    const entries = buildLeaderboardStandings({
      count: 0,
      player: { id: 'p', displayName: 'P', rating: 9999, stats: { matchesPlayed: 40, wins: 10 } },
    });
    expect(entries).toHaveLength(1);
    expect(entries[0]!.rating).toBe(3500);
    expect(entries[0]!.stats.winRate).toBe(0.25);
    expect(entries[0]!.rank).toBe(1);
  });

  it('round-trips the saved rating through storage', () => {
    const storage = memoryStorage();
    expect(loadPlayerRating(storage)).toBe(DEFAULT_PLAYER_RATING);
    expect(savePlayerRating(1487.6, storage)).toBe(true);
    expect(storage.getItem(PLAYER_RATING_STORAGE_KEY)).toBe('1488');
    expect(loadPlayerRating(storage)).toBe(1488);
    storage.setItem(PLAYER_RATING_STORAGE_KEY, 'not-a-number');
    expect(loadPlayerRating(storage)).toBe(DEFAULT_PLAYER_RATING);
  });
});
